<?php
function workflow_controls(string $transition,string $label,array $state,string $style='primary'): void { ?>
<form method="post" <?= $transition==='finalize'?'data-confirm="Muktamadkan versi ini dan terbitkan surat lantikan?"':'' ?>><?= csrf() ?><input type="hidden" name="action" value="workflow"><input type="hidden" name="transition" value="<?= $transition ?>"><input type="hidden" name="version" value="<?= $state['version'] ?>"><button class="btn <?= $style ?>"><?= e($label) ?></button></form>
<?php }
function workflow_page(array $account): void {
 $state=workflow_state(); $revision=$state['revision_id']?q('SELECT r.*,s.name AS submitter,a.name AS approver FROM workflow_revisions r JOIN accounts s ON s.id=r.submitted_by LEFT JOIN accounts a ON a.id=r.approved_by WHERE r.id=?',[$state['revision_id']])->fetch():null;
 $source=$state['status']==='draft'?workflow_source():json_decode($revision['payload'],true,64,JSON_THROW_ON_ERROR);
 $names=array_column($source['teachers'],'name','id'); $loads=array_fill_keys(array_column($source['teachers'],'id'),0); foreach($source['positions'] as $p) if($p['teacher_id']!==null)$loads[$p['teacher_id']]+=$p['weight']; $overloaded=array_filter($source['teachers'],fn($t)=>$loads[$t['id']]>$t['capacity']); $tasks=array_filter($source['positions'],fn($p)=>$p['teacher_id']!==null); $published=workflow_published();
?>
<div class="page-heading"><div><span class="eyebrow teal">KEPUTUSAN & TANGGUNGJAWAB</span><h1>Semakan & Kelulusan</h1><p class="muted">Semak agihan, rekod keputusan dan terbitkan lantikan rasmi sekolah.</p></div><span class="pill <?= $state['status']==='finalized'?'green':'amber' ?>"><?= WORKFLOW_LABELS[$state['status']] ?></span></div>
<section class="workflow-progress"><?php foreach(WORKFLOW_LABELS as $key=>$label): ?><div class="<?= $state['status']===$key?'current':'' ?>"><span><?= array_search($key,array_keys(WORKFLOW_LABELS))+1 ?></span><strong><?= $label ?></strong></div><?php endforeach ?></section>
<section class="panel"><div class="panel-heading"><div><h3><?= $state['status']==='draft'?'Draf agihan semasa':'Semakan versi #'.$state['revision_id'] ?></h3><p class="muted"><?= count($tasks) ?> lantikan · <?= count($source['positions'])-count($tasks) ?> jawatan kosong · Sesi <?= e($source['school']['year']) ?></p></div><?php if(auth_can_plan($account)&&$state['status']==='draft'): ?><a class="btn outline" href="/?page=assignments">Sunting draf</a><?php endif ?></div>
<div class="workflow-note"><?php if($state['status']==='draft'): ?><p>Agihan masih boleh disunting oleh Pentadbir dan PK. Hantar draf untuk mengunci data dan mendapatkan semakan <?= e(school_head_title()) ?>.</p><?php else: ?><p>Dihantar oleh <strong><?= e($revision['submitter']) ?></strong> pada <?= e(workflow_local_time($revision['submitted_at'])) ?> MYT. Data dikunci sehingga dikembalikan kepada draf.</p><?php endif ?><?php if($state['status']!=='draft'&&$revision&&$revision['approved_at']): ?><p>Diluluskan oleh <?= e($revision['approver']) ?> pada <?= e(workflow_local_time($revision['approved_at'])) ?> MYT.</p><?php endif ?><?php if($published): ?><p class="muted">Surat dan paparan guru menggunakan versi muktamad #<?= $published['id'] ?>. Pindaan draf tidak mengubah dokumen yang telah diterbitkan.</p><?php else: ?><p class="muted">Belum ada versi muktamad. Surat lantikan dan tugas guru akan tersedia selepas pemuktamadan.</p><?php endif ?></div>
<?php if($overloaded): ?><div class="notice error workflow-load-notice"><?= count($overloaded) ?> guru melebihi kapasiti mata. Semak beban sebelum meluluskan.</div><?php endif ?>
<details class="plan-details"><summary>Beban guru dalam versi ini</summary><div class="table-wrap"><table><thead><tr><th>Guru</th><th>Mata / kapasiti</th><th>Status</th></tr></thead><tbody><?php foreach($source['teachers'] as $t): ?><tr><td><?= e($t['name']) ?></td><td><?= $loads[$t['id']] ?> / <?= $t['capacity'] ?></td><td><?= $loads[$t['id']]>$t['capacity']?'Melebihi kapasiti':'Dalam kapasiti' ?></td></tr><?php endforeach ?></tbody></table></div></details>
<div class="workflow-actions"><?php if($state['status']==='draft'&&auth_can_plan($account)): workflow_controls('submit','Hantar untuk semakan',$state); endif ?><?php if($account['role']==='head'&&$state['status']==='submitted'): workflow_controls('approve','Luluskan agihan',$state); endif ?><?php if($account['role']==='head'&&$state['status']==='approved'): workflow_controls('finalize','Muktamadkan & terbitkan surat',$state); endif ?><?php if($state['status']==='finalized'): ?><a class="btn primary" href="/?page=letters">Lihat surat muktamad</a><?php endif ?></div>
<?php if($state['status']!=='draft'&&in_array($account['role'],['admin','head'],true)): ?><form method="post" class="workflow-return"><?= csrf() ?><input type="hidden" name="action" value="workflow"><input type="hidden" name="transition" value="return"><input type="hidden" name="version" value="<?= $state['version'] ?>"><label class="field">Sebab dikembalikan / pindaan<input name="reason" required maxlength="500" placeholder="Nyatakan perkara yang perlu disemak"></label><button class="btn outline"><?= $state['status']==='finalized'?'Buka draf pindaan':'Kembalikan kepada draf' ?></button></form><?php endif ?>
<div class="table-wrap"><table><thead><tr><th>Jawatan</th><th>Bidang</th><th>Pemberat</th><th>Penyandang</th></tr></thead><tbody><?php foreach($source['positions'] as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category']) ?></td><td><?= $p['weight'] ?> mata</td><td><?= e($names[$p['teacher_id']??0]??'Belum diisi') ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h3>Sejarah versi semakan</h3></div><div class="table-wrap"><table><thead><tr><th>Versi</th><th>Status</th><th>Penghantar</th><th>Tarikh dihantar (MYT)</th><th>Sebab dikembalikan</th></tr></thead><tbody><?php foreach(q('SELECT r.*,a.name FROM workflow_revisions r JOIN accounts a ON a.id=r.submitted_by ORDER BY r.id DESC LIMIT 30')->fetchAll() as $r): ?><tr><td>#<?= $r['id'] ?></td><td><?= e(WORKFLOW_LABELS[$r['status']]??'Dikembalikan') ?></td><td><?= e($r['name']) ?></td><td><?= e(workflow_local_time($r['submitted_at'])) ?></td><td class="reason-cell"><?= e($r['return_reason']??'—') ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php }
function accounts_page(array $account,array $teachers): void {
 $edit=isset($_GET['edit'])?q('SELECT id,name,email,role,teacher_id,active FROM accounts WHERE id=?',[(int)$_GET['edit']])->fetch():null;
?>
<div class="page-heading"><div><span class="eyebrow teal">AKSES MENGIKUT PERANAN</span><h1>Akaun Pengguna</h1><p class="muted">Sediakan akaun PK, <?= e(school_head_title()) ?> dan Guru untuk sekolah ini.</p></div><a class="btn primary" href="/?page=accounts&new=1#account-editor">Tambah akaun</a></div>
<?php if($edit||isset($_GET['new'])): ?><section class="panel" id="account-editor"><div class="panel-heading"><h3><?= $edit?'Sunting akaun':'Akaun baharu' ?></h3><a class="text-link" href="/?page=accounts">Tutup</a></div><form method="post" class="form-grid"><?= csrf() ?><input type="hidden" name="action" value="account_save"><input type="hidden" name="id" value="<?= $edit['id']??0 ?>"><?php field('Nama','name',$edit['name']??'','text','required maxlength="160"'); field('E-mel log masuk','email',$edit['email']??'','email','required maxlength="254"'); ?><label class="field">Peranan<select name="role"><?php foreach(role_labels() as $k=>$label): ?><option value="<?= $k ?>" <?= ($edit['role']??'pk')===$k?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label class="field">Profil guru (wajib untuk peranan Guru)<select name="teacher_id"><option value="">Tiada</option><?php foreach($teachers as $t): ?><option value="<?= $t['id'] ?>" <?= ($edit['teacher_id']??null)===$t['id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach ?></select></label><label class="field full-span"><?= $edit?'Kata laluan baharu (kosongkan untuk kekalkan)':'Kata laluan' ?><input type="password" name="password" autocomplete="new-password" minlength="12" maxlength="72" <?= $edit?'':'required' ?>><small class="muted">Sekurang-kurangnya 12 aksara. Pengguna boleh menukar sendiri selepas log masuk.</small></label><label class="check-field full-span"><input type="checkbox" name="active" <?= !$edit||$edit['active']?'checked':'' ?>><span>Akaun aktif</span></label><div class="form-actions"><button class="btn primary">Simpan akaun</button></div></form></section><?php endif ?>
<section class="panel"><div class="panel-heading"><h3>Senarai akaun sekolah</h3></div><div class="table-wrap"><table><thead><tr><th>Nama / e-mel</th><th>Peranan</th><th>Profil guru</th><th>Status</th><th></th></tr></thead><tbody><?php foreach(q('SELECT a.id,a.name,a.email,a.role,a.active,t.name AS teacher_name FROM accounts a LEFT JOIN teachers t ON t.id=a.teacher_id ORDER BY a.name')->fetchAll() as $a): ?><tr><td><strong><?= e($a['name']) ?></strong><small class="cell-sub"><?= e($a['email']) ?></small></td><td><?= e(role_label($a['role'])) ?></td><td><?= e($a['teacher_name']??'—') ?></td><td><?= $a['active']?'Aktif':'Tidak aktif' ?></td><td><a class="text-link" href="/?page=accounts&edit=<?= $a['id'] ?>#account-editor">Sunting</a></td></tr><?php endforeach ?></tbody></table></div></section>
<?php }
function profile_page(array $account): void { ?>
<div class="page-heading"><div><span class="eyebrow teal">AKAUN SAYA</span><h1>Profil & Kata Laluan</h1><p class="muted"><?= e($account['name']) ?> · <?= e($account['email']) ?> · <?= e(role_label($account['role'])) ?></p></div></div><section class="panel"><div class="panel-heading"><h3>Tukar kata laluan</h3></div><form method="post" class="form-grid"><?= csrf() ?><input type="hidden" name="action" value="profile_password"><label class="field full-span">Kata laluan semasa<input type="password" name="current_password" required autocomplete="current-password" maxlength="72"></label><label class="field">Kata laluan baharu<input type="password" name="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><label class="field">Sahkan kata laluan baharu<input type="password" name="confirm_password" required minlength="12" maxlength="72" autocomplete="new-password"></label><div class="form-actions"><button class="btn primary">Tukar kata laluan</button></div></form></section>
<?php }
function finalized_letter_html(array $doc): void {
 $teacher=$doc['teacher']; $school=$doc['school']; $tasks=$doc['assignments'];
 $issued=(new DateTimeImmutable($doc['finalized_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Kuala_Lumpur'))->format('d/m/Y');
?>
<?php $branding=$school['branding']??null; $left=$branding&&in_array($branding['layout'],['dual','national'],true)?($branding['national_crest']??null):null; $right=$branding&&in_array($branding['layout'],['dual','school'],true)?($branding['school_logo']??null):null; ?>
<article class="letter"><header><div class="letter-identities"><?php if($left): ?><img src="<?= e(branding_image_url($left)) ?>" alt="Jata Negara" class="letter-emblem"><?php endif ?><?php if($right): ?><img src="<?= e(branding_image_url($right)) ?>" alt="Logo sekolah" class="letter-emblem"><?php endif ?></div><h2><?= e($school['school']) ?></h2><p>PEJABAT <?= e(mb_strtoupper(school_head_title($school))) ?> · VERSI MUKTAMAD #<?= $doc['revision_id'] ?></p></header><div class="letter-meta">Ruj. Kami: <?= e($school['reference']) ?> (<?= $teacher['id'] ?> / V<?= $doc['revision_id'] ?>)<br>Tarikh: <?= $issued ?></div><p><strong><?= e($teacher['name']) ?></strong><br><?= e($school['school']) ?></p><p>Tuan/Puan,</p><h3>PELANTIKAN TUGAS DAN TANGGUNGJAWAB BAGI SESI <?= e($school['year']) ?></h3><p>Dengan hormatnya perkara di atas dirujuk.</p><p>2. Sukacita dimaklumkan bahawa tuan/puan dilantik untuk menjalankan tugas berikut bagi sesi <?= e($school['year']) ?>:</p><table><thead><tr><th>Bil.</th><th>Jawatan</th><th>Bidang</th></tr></thead><tbody><?php foreach($tasks as $i=>$p): ?><tr><td><?= $i+1 ?></td><td><?= e($p['name']) ?></td><td><?= e($p['category']) ?></td></tr><?php endforeach ?></tbody></table><p>3. Kerjasama dan komitmen tuan/puan dalam melaksanakan tanggungjawab ini amat dihargai. Sebarang perubahan tugas akan dimaklumkan oleh pihak pentadbiran sekolah.</p><p>Sekian, terima kasih.</p><p>“BERKHIDMAT UNTUK NEGARA”</p><div class="signature">........................................................<br><strong><?= e($school['principal']) ?></strong><br><?= e(school_head_title($school)) ?><br><?= e($school['school']) ?></div></article>
<?php }
function published_letters_page(array $account): void {
 $published=workflow_published(); $selected=(int)($_GET['teacher']??0); $all=isset($_GET['all']);
?>
<div class="page-heading no-print"><div><span class="eyebrow teal">DOKUMEN YANG TELAH DIMUKTAMADKAN</span><h1>Surat Lantikan</h1><p class="muted">Surat menggunakan salinan tetap agihan muktamad, termasuk nama sekolah dan ketua sekolah.</p></div><?php if($published): ?><a class="btn outline" href="/?page=letters&all=1">Semua surat</a><?php endif ?></div>
<?php if(!$published): ?><section class="panel empty"><h3>Belum ada agihan muktamad</h3><p>Hantar draf untuk semakan <?= e(school_head_title()) ?> dan muktamadkan sebelum menjana surat.</p><a class="btn outline" href="/?page=workflow">Semakan & kelulusan</a></section><?php return; endif ?>
<section class="panel no-print"><form method="get" class="letter-controls"><input type="hidden" name="page" value="letters"><label class="field">Pilih guru<select name="teacher" required><option value="">Pilih nama guru</option><?php foreach($published['data']['teachers'] as $t): ?><option value="<?= $t['id'] ?>" <?= $selected===$t['id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach ?></select></label><button class="btn primary">Pratonton surat</button><?php if($selected||$all): ?><button class="btn outline" type="button" data-print>Cetak / PDF</button><?php endif ?></form><p class="muted letter-warning">Versi muktamad #<?= $published['id'] ?>. Pindaan draf tidak mengubah surat ini sehingga versi baharu dimuktamadkan.</p></section>
<?php $shown=0; foreach($published['data']['teachers'] as $t) {
 if(!$all&&$selected!==$t['id'])continue; $doc=workflow_letter($t['id']); if(!$doc['assignments'])continue; $shown++; finalized_letter_html($doc);
 } if(!$shown): ?><section class="panel empty"><p>Pilih guru yang mempunyai lantikan dalam versi muktamad ini.</p></section><?php endif ?>
<?php }
function my_tasks_page(array $account): void {
 $published=workflow_published(); $doc=null;
 if($published) { try { $doc=workflow_letter((int)$account['teacher_id']); } catch(WorkflowError) {} }
?>
<div class="page-heading no-print"><div><span class="eyebrow teal">LANTIKAN SAYA</span><h1>Tugas Saya</h1><p class="muted">Selamat datang, <?= e($account['name']) ?>. Paparan ini menunjukkan tugas anda yang telah dimuktamadkan.</p></div><?php if($doc&&$doc['assignments']): ?><button class="btn primary" data-print>Cetak surat saya</button><?php endif ?></div>
<?php if(!$doc||!$doc['assignments']): ?><section class="panel empty"><h3>Belum ada lantikan muktamad untuk anda</h3><p>Hubungi pentadbir sekolah jika anda memerlukan semakan.</p></section><?php else: finalized_letter_html($doc); endif ?>
<?php }
